/// An attachment of a demo message and where its bytes come from.
final class DemoAttachment {
  const DemoAttachment(this.attachment, {this.asset, this.generate});

  final Attachment attachment;

  /// Asset path of the bytes (images).
  final String? asset;

  /// Generated bytes (PDFs, calendar files, documents).
  final Uint8List Function()? generate;
}

/// One message of the demo mailbox: its summary plus everything needed to
/// produce its content and raw source.
final class DemoMessage {
  DemoMessage({
    required this.summary,
    this.html,
    this.text,
    this.isFlowed = false,
    this.attachments = const [],
    this.extraHeaders = const [],
    this.authenticationFails = false,
  });

  EmailSummary summary;
  final String? html;
  final String? text;
  final bool isFlowed;
  final List<DemoAttachment> attachments;

  /// Headers beyond the standard ones (List-Id, X-Mailer…).
  final List<(String, String)> extraHeaders;

  /// Fails DKIM/SPF/DMARC in Authentication-Results (the phishing message).
  final bool authenticationFails;

  String get id => summary.id;
}

