/// Everything the demo repository starts with.
final class DemoSeed {
  DemoSeed._(this.now, int seed) : _random = Random(seed);

  /// Builds the demo mailbox relative to [now]. The same [seed] always gives
  /// the same mailbox.
  factory DemoSeed.build(DateTime now, {int seed = 7}) => DemoSeed._(now, seed).._build();

  final DateTime now;
  final Random _random;
  int _next = 1;

  final accounts = <MailAccount>[];
  final mailboxes = <Mailbox>[];

  /// Messages synced locally.
  final messages = <DemoMessage>[];

  /// Older messages per mailbox id, newest first, paged in by loadOlder.
  final older = <String, List<DemoMessage>>{};

  /// Messages only the "server" has (found by server search), per account.
  final serverOnly = <String, List<DemoMessage>>{};

  final _threadRefs = <String, List<String>>{};

  // Accounts and folders --------------------------------------------------------

  void _build() {
    _accounts();
    _personal();
    _work();
    _fastmail();
    _filler();
    _olderMail();
    _serverMail();
  }

