    void box(String account, String path, {MailboxRole role = MailboxRole.none, bool selectable = true}) {
      final slash = path.lastIndexOf('/');
      mailboxes.add(
        Mailbox(
          id: MailIds.mailbox(account, path),
          accountId: account,
          name: slash < 0 ? (path == 'INBOX' ? 'Inbox' : path) : path.substring(slash + 1),
          path: path,
          role: role,
          parentId: slash < 0 ? null : MailIds.mailbox(account, path.substring(0, slash)),
          isSelectable: selectable,
          sortOrder: mailboxes.length,
        ),
      );
    }

    const p = DemoAccounts.personal;
    box(p, 'INBOX', role: MailboxRole.inbox);
