  // Helpers ---------------------------------------------------------------------

  /// A time [daysAgo] calendar days back at [hour]:[minute]; today's times
  /// that would lie in the future are pulled into the past.
  DateTime at(int daysAgo, int hour, [int minute = 0]) {
    final t = DateTime(now.year, now.month, now.day - daysAgo, hour, minute);
    if (!t.isAfter(now)) return t;
    return now.subtract(Duration(minutes: 3 + (hour * 13 + minute) % 170));
  }

  DateTime minutesAgo(int minutes) => now.subtract(Duration(minutes: minutes));

  EmailAddress _me(String account) => switch (account) {
    DemoAccounts.work => DemoPeople.work,
    DemoAccounts.fastmail => DemoPeople.fastmail,
    _ => DemoPeople.personal,
  };

  /// Adds a message. [thread] links messages of one conversation (Message-ID,
  /// In-Reply-To, References). [into] picks the pool: local by default.
  DemoMessage add({
    required String account,
    required String box,
    required DateTime at,
    required EmailAddress from,
    required String subject,
    List<EmailAddress>? to,
    List<EmailAddress> cc = const [],
    String? text,
    String? html,
    bool isFlowed = false,
    bool unread = false,
    bool flagged = false,
    bool answered = false,
    bool forwarded = false,
    Set<String> tags = const {},
    String? thread,
    List<DemoAttachment> attachments = const [],
    List<(String, String)> headers = const [],
    bool authenticationFails = false,
    List<DemoMessage>? into,
  }) {
    final n = _next++;
    final domain = from.domain.isEmpty ? 'example.com' : from.domain;
    final messageId = '${thread ?? 'm'}.$n.${at.millisecondsSinceEpoch.toRadixString(36)}@$domain';
    final refs = thread == null ? const <String>[] : (_threadRefs[thread] ??= []);
    final keywords = <String>{
      if (!unread) Keywords.seen,
      if (flagged) Keywords.flagged,
      if (answered) Keywords.answered,
      if (forwarded) Keywords.forwarded,
      ...tags,
    };
    final mailboxId = MailIds.mailbox(account, box);
    final role = mailboxes.firstWhere((m) => m.id == mailboxId).role;
    if (role == MailboxRole.drafts) keywords.addAll({Keywords.draft, Keywords.seen});
    if (role == MailboxRole.sent) keywords.add(Keywords.seen);
    // Like real clients, preview the HTML part when there is one (preheaders included).
    final body = html != null ? htmlToPreviewText(html) : text ?? '';
    final summary = EmailSummary(
      id: MailIds.jmapEmail(account, 'M$n'),
      accountId: account,
      mailboxId: mailboxId,
      receivedAt: at,
      sentAt: at.subtract(Duration(seconds: 20 + n % 90)),
      threadId: thread == null ? 'T$n' : 'T-$account-$thread',
      messageIdHeader: messageId,
      inReplyTo: refs.isEmpty ? null : refs.last,
      references: List.of(refs),
      from: [from],
      to: to ?? [_me(account)],
      cc: cc,
      subject: subject,
      preview: makePreview(body),
      size: (html?.length ?? 0) + (text?.length ?? 0) + 1800 + attachments.fold(0, (s, a) => s + a.attachment.size),
      keywords: keywords,
      hasAttachment: attachments.any((a) => !a.attachment.isInline),
    );
    if (thread != null) refs.add(messageId);
    final message = DemoMessage(
      summary: summary,
      html: html,
      text: text,
      isFlowed: isFlowed,
      attachments: attachments,
      extraHeaders: headers,
      authenticationFails: authenticationFails,
    );
    (into ?? messages).add(message);
    return message;
  }

  static DemoAttachment pdf(String partId, String name, String title, {int size = 184320}) => DemoAttachment(
    Attachment(partId: partId, mimeType: 'application/pdf', filename: name, size: size),
    generate: () => tinyPdf(title),
  );

  static DemoAttachment inlineImage(String partId, String cid, String asset, String name, int size) => DemoAttachment(
    Attachment(
      partId: partId,
      mimeType: asset.endsWith('.png') ? 'image/png' : 'image/jpeg',
      filename: name,
      size: size,
      contentId: cid,
      isInline: true,
    ),
    asset: asset,
  );

  static DemoAttachment calendarInvite(String partId, String summary, DateTime start) => DemoAttachment(
    Attachment(partId: partId, mimeType: 'text/calendar', filename: 'invite.ics', size: 1240),
    generate: () => calendarFile(summary, start),
  );

  static DemoAttachment document(String partId, String name, String mime, int size) => DemoAttachment(
    Attachment(partId: partId, mimeType: mime, filename: name, size: size),
    generate: () => Uint8List.fromList(List.generate(512, (i) => (i * 31 + 7) % 256)),
  );

