      final (topic, from, text) = listTopics[i % listTopics.length];
      add(
        account: f,
        box: 'Lists/Open Garden',
        at: at(d + 1, 8 + _random.nextInt(14), _random.nextInt(60)),
        from: from,
        to: [DemoPeople.gardenList],
        subject: '${i >= listTopics.length ? 'Re: ' : ''}[open-garden] $topic',
        text:
            '$text\n\n-- \n${from.displayName}\n\n_______________________________________________\nopen-garden mailing list',
        unread: d < 3,
        headers: _listHeaders,
      );
    }
    for (final (i, d) in _days(6, maxDays: 42).indexed) {
      final issue = 46 - i;
      add(
        account: f,
        box: i == 0 ? 'INBOX' : 'Newsletters',
        at: at(d + 1, 6, 30),
        from: DemoPeople.fieldNotes,
        subject:
            'Field Notes #$issue: ${_pick(['Slow software', 'The case for paper maps', 'Repair, not replace', 'Small web, big ideas', 'Notes on attention', 'Winter light'])}',
        html:
            '<div style="max-width:560px;font-family:Georgia,serif;font-size:17px;line-height:1.6;color:#2b2b2b">'
            '<div style="display:none">Five links, one essay and a photo from the coast.</div>'
            '<h1 style="font-size:26px">Field Notes #$issue</h1>'
            '<p>Hello friends — this week I have been thinking about tools that stay out of the way. '
            'The best ones disappear: you notice the work, not the tool.</p>'
            '<p><b>Five links</b></p><ol><li>A tiny forum that has run since 2003</li><li>Why maps fold the way they do</li>'
            '<li>An ode to the paperclip</li><li>Repair cafés, counted</li><li>A slow radio station from the north</li></ol>'
            '<p>Until next week,<br>Mira</p>'
            '<img src="https://pixel.fieldnotes.example/open/$issue.gif" width="1" height="1" alt=""></div>',
        unread: d < 5,
        tags: {Keywords.label5},
        headers: _newsletterHeaders('fieldnotes.example'),
      );
    }
    final pals = [
      (DemoPeople.felix, 'Repair café on the 15th', 'Bring anything with a plug. The soldering station is back.'),
      (DemoPeople.noor, 'Coffee next week?', 'I am in town Tuesday and Wednesday. Same place as last time?'),
      (DemoPeople.kai, 'Seeds!', 'I saved too many tomato seeds again. Want some Black Krim?'),
    ];
    for (final (i, d) in _days(pals.length, maxDays: 30).indexed) {
      final (from, subject, text) = pals[i];
      add(
        account: f,
        box: i == 2 ? 'Archive' : 'INBOX',
        at: at(d + 2, 19, 10 + i * 7),
        from: from,
        subject: subject,
        text: text,
        answered: i != 1,
      );
    }
    for (final d in _days(2, maxDays: 40)) {
      add(
        account: f,
        box: 'Trash',
        at: at(d + 1, 12),
        from: DemoPeople.fieldNotes,
        subject: 'Your subscription is confirmed',
        text: 'Thanks for subscribing to Field Notes Weekly.',
      );
    }
  }

