/// Collapses whitespace into a list preview of at most 256 characters.
String makePreview(String text) {
  final collapsed = text
      .split('\n')
      // Quotes and their "On …, X wrote:" lines say nothing new.
      .where((l) => !l.trimLeft().startsWith('>') && !l.trimRight().endsWith('wrote:'))
      .join(' ')
      .replaceAll(RegExp(r'\s+'), ' ')
      .trim();
  return collapsed.length <= 256 ? collapsed : collapsed.substring(0, 256);
}

/// Rough HTML-to-text for previews and the text/plain alternative.
String htmlToPreviewText(String html) => html
    .replaceAll(RegExp(r'<(style|script|title)[^>]*>.*?</\1>', caseSensitive: false, dotAll: true), ' ')
    .replaceAll(RegExp(r'<br\s*/?>|</p>|</div>|</tr>|</h\d>|</li>', caseSensitive: false), '\n')
    .replaceAll(RegExp(r'<[^>]+>'), ' ')
    .replaceAll('&nbsp;', ' ')
    .replaceAll('&zwnj;', '')
    .replaceAll('&amp;', '&')
    .replaceAll('&mdash;', '—')
    .replaceAll('&#8212;', '—')
    .replaceAll('&lt;', '<')
    .replaceAll('&gt;', '>')
    .replaceAll(RegExp(r'[ \t]+'), ' ')
    .replaceAll(RegExp(r'\n\s*\n\s*\n+'), '\n\n')
    .trim();
